window.addEventListener('resize',()=>{setView(view);});

const pathNodes=new Map();
function syncPaths(markup){
 const desired=new Set();const template=document.createElement('template');
 for(const html of markup){const id=html.match(/data-id="([^"]+)"/)[1];desired.add(id);const previous=pathNodes.get(id);if(previous?.html===html)continue;
 template.innerHTML='<svg xmlns="http://www.w3.org/2000/svg">'+html+'</svg>';const fresh=template.content.firstElementChild.firstElementChild;
 if(previous){for(const name of fresh.getAttributeNames())if(previous.node.getAttribute(name)!==fresh.getAttribute(name))previous.node.setAttribute(name,fresh.getAttribute(name));previous.html=html;}else{const node=fresh.cloneNode(true);$('polygons').append(node);pathNodes.set(id,{node,html});}}
 for(const [id,value] of pathNodes)if(!desired.has(id)){value.node.remove();pathNodes.delete(id);}
}

let resizeStart=null;
$('detailResize').addEventListener('pointerdown',e=>{resizeStart={x:e.clientX,width:document.querySelector('.right').getBoundingClientRect().width};e.target.setPointerCapture(e.pointerId);});
$('detailResize').addEventListener('pointermove',e=>{if(!resizeStart)return;document.body.style.setProperty('--detail',Math.max(310,Math.min(innerWidth*.55,resizeStart.width+resizeStart.x-e.clientX))+'px');});
$('detailResize').addEventListener('pointerup',()=>{resizeStart=null;updateTiles();});
$('detailResize').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const w=document.querySelector('.right').getBoundingClientRect().width;document.body.style.setProperty('--detail',Math.max(310,Math.min(innerWidth*.55,w+(e.key==='ArrowLeft'?20:-20)))+'px');updateTiles();}});

function bindExport(){$('exportPDF').onclick=()=>{ $('modal').close();exportAtlas();};$('exportPNG').onclick=()=>{$('modal').close();exportAtlas('png');};}

async function addExportLegend(pdf){
 const font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);let p=pdf.addPage([595,842]),y=800;
 const lines=['ATLAS HPC - Nivel -1 / A-W, 1-12',...($('activeLegend').hidden?['Plano monocromatico / consulta actual']:[$('activeLegend').innerText]),'Superficies auxiliares de consulta. No certifican limites tecnicos.','Fuentes: '+data.documents.map(d=>d.code+' ('+d.revision+')').join('; ')];
 for(const raw of lines){const words=raw.replace(/[^\x20-\xFF\n]/g,'-').split(/\s+/);let line='';for(const word of words){if(font.widthOfTextAtSize(line+' '+word,10)>510){p.drawText(line,{x:40,y,size:10,font});y-=16;line=word;if(y<40){p=pdf.addPage([595,842]);y=800;}}else line+=(line?' ':'')+word;}if(line){p.drawText(line,{x:40,y,size:10,font});y-=22;}}
}

function revertLast(r){const old=JSON.parse(r.history[0].before_json);modal(`<h2>Revertir última corrección</h2><p>${esc(r.code)} · Se conservará todo el historial.</p><form id="revertForm"><label>Responsable<input name="responsible" required></label><label>Motivo<textarea name="reason" required></textarea></label><button class="primary">Guardar reversión</button></form>`);$('revertForm').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);const b={version:r.version,responsible:f.get('responsible'),reason:'Reversión: '+f.get('reason'),code:old.code,name:old.name,finishes:old.finishes,diamond_bbox:old.diamond_bbox,polygon:old.polygon,holes:old.holes,geometry_status:'Pendiente de revisión',status:'Pendiente de revisión'};const saved=await api('/api/rooms/'+r.id,{method:'PATCH',body:JSON.stringify(b)});data.rooms[data.rooms.findIndex(x=>x.id===r.id)]=saved;selected=saved;await prepareViewer(atlas,uniqueRooms(data.rooms),aliases,await loadRuntime());$('modal').close();await runSearch();selected=saved;renderDetail();render();toast('Reversión guardada como nueva corrección, pendiente de revisión.');}catch(err){toast(err.message);}};}
